<script setup>import AppShell from'../../Layouts/AppShell.vue';import PageHeader from'../../Components/PageHeader.vue';import StateCard from'../../Components/StateCard.vue';import UiBadge from'../../Components/UiBadge.vue';import UiButton from'../../Components/UiButton.vue';import{Head,router}from'@inertiajs/vue3';import{onBeforeUnmount,onMounted,ref}from'vue';const p=defineProps({event:Object,batches:Array,exports:Array,indexRun:Object});const timer=ref(),tone=s=>s==='completed'?'success':s==='failed'?'error':['queued','processing'].includes(s)?'warning':'info';onMounted(()=>timer.value=setInterval(()=>router.reload({only:['batches','exports','indexRun'],preserveScroll:true}),3000));onBeforeUnmount(()=>clearInterval(timer.value));</script><template><AppShell><Head title="Processing & exports"/><div class="lp-page"><PageHeader eyebrow="Durable operations" :title="`Processing · ${event.name}`" description="Upload, indexing and export states refresh automatically from queue-backed records."><UiButton variant="secondary" :href="`/groups/${event.id}`">Event workspace</UiButton></PageHeader><div class="mt-8 grid gap-6 xl:grid-cols-2"><section><h2 class="text-xl font-bold">Upload batches</h2><StateCard v-if="!batches.length" class="mt-4" title="No upload batches" message="New uploads will appear here with per-file progress."/><div v-else class="mt-4 space-y-3"><UiCard v-for="b in batches" :key="b.uuid"><div class="flex justify-between gap-3"><div><p class="font-semibold">{{b.total_files}} files</p><p class="text-xs text-slate-500">{{b.completed_files}} complete · {{b.failed_files}} failed</p></div><UiBadge :tone="tone(b.state)">{{b.state}}</UiBadge></div></UiCard></div></section><section><h2 class="text-xl font-bold">Exports</h2><StateCard v-if="!exports.length" class="mt-4" title="No exports" message="Select authorized photographs to create an export."/><div v-else class="mt-4 space-y-3"><UiCard v-for="e in exports" :key="e.uuid"><div class="flex justify-between gap-3"><p class="font-semibold">{{e.photo_ids.length}} photos</p><UiBadge :tone="tone(e.state)">{{e.state}}</UiBadge></div><UiButton v-if="e.state==='completed'" class="mt-4" :href="`/exports/${e.uuid}/download`">Download ZIP</UiButton><p v-if="e.error" class="lp-error">{{e.error}}</p></UiCard></div></section></div><UiCard class="mt-6"><div class="flex justify-between gap-4"><div><h2 class="text-lg font-bold">Face indexing</h2><p class="text-sm text-slate-500">{{indexRun?.completed||0}} / {{indexRun?.total||0}} processed</p></div><UiBadge :tone="tone(indexRun?.state||'not_started')">{{indexRun?.state||'not started'}}</UiBadge></div></UiCard></div></AppShell></template>
